-- Shareable IDs are distinct from internal UUIDs. They are generated by the
-- database, never accepted as authorization, and are safe to show in the UI.
create function app_private.new_jibon_user_id()
returns text language plpgsql security definer set search_path = '' as $$
declare candidate text;
begin
  loop
    candidate := 'JBN-U-' || upper(substr(replace(gen_random_uuid()::text, '-', ''), 1, 10));
    exit when not exists (select 1 from public.profiles where jibon_id = candidate);
  end loop;
  return candidate;
end;
$$;

create function app_private.new_family_invite_code()
returns text language plpgsql security definer set search_path = '' as $$
declare candidate text;
begin
  loop
    candidate := 'JBN-F-' || upper(substr(replace(gen_random_uuid()::text, '-', ''), 1, 10));
    exit when not exists (select 1 from public.families where invite_code = candidate);
  end loop;
  return candidate;
end;
$$;

alter table public.profiles add column jibon_id text;
update public.profiles set jibon_id = app_private.new_jibon_user_id() where jibon_id is null;
alter table public.profiles alter column jibon_id set not null;
alter table public.profiles alter column jibon_id set default app_private.new_jibon_user_id();
alter table public.profiles add constraint profiles_jibon_id_key unique (jibon_id);
alter table public.profiles add constraint profiles_jibon_id_format check (jibon_id ~ '^JBN-U-[A-F0-9]{10}$');

alter table public.families add column invite_code text;
alter table public.families add column invite_code_enabled boolean not null default true;
alter table public.families add column invite_code_rotated_at timestamptz not null default now();
update public.families set invite_code = app_private.new_family_invite_code() where invite_code is null;
alter table public.families alter column invite_code set not null;
alter table public.families alter column invite_code set default app_private.new_family_invite_code();
alter table public.families add constraint families_invite_code_key unique (invite_code);
alter table public.families add constraint families_invite_code_format check (invite_code ~ '^JBN-F-[A-F0-9]{10}$');

alter table public.family_invitations
  add column invited_user_id uuid references auth.users(id) on delete set null;
create unique index family_invitations_one_pending_user_idx
  on public.family_invitations (family_id, invited_user_id)
  where status = 'pending' and invited_user_id is not null;
create index family_invitations_recipient_status_idx
  on public.family_invitations (invited_user_id, status, expires_at)
  where invited_user_id is not null;

create table public.family_join_requests (
  id uuid primary key default gen_random_uuid(),
  family_id uuid not null references public.families(id) on delete cascade,
  requester_user_id uuid not null references auth.users(id) on delete cascade,
  status text not null default 'pending' check (status in ('pending', 'approved', 'declined', 'cancelled')),
  reviewed_by uuid references auth.users(id) on delete set null,
  reviewed_at timestamptz,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  check ((status in ('approved', 'declined')) = (reviewed_at is not null)),
  check ((status in ('approved', 'declined')) = (reviewed_by is not null))
);
create unique index family_join_requests_one_pending_requester_idx
  on public.family_join_requests (family_id, requester_user_id) where status = 'pending';
create index family_join_requests_family_status_idx
  on public.family_join_requests (family_id, status, created_at desc);
create trigger family_join_requests_updated_at before update on public.family_join_requests
  for each row execute function app_private.set_updated_at();
revoke all on public.family_join_requests from anon, authenticated;
alter table public.family_join_requests enable row level security;

create or replace function public.get_my_family_invitations()
returns table (invitation_id uuid, family_name text, expires_at timestamptz, created_at timestamptz)
language plpgsql security definer set search_path = '' as $$
declare actor_id uuid := (select auth.uid()); actor_email text := lower(coalesce((select auth.jwt() ->> 'email'), ''));
begin
  if actor_id is null then raise exception 'Authentication is required'; end if;
  return query
    select invitation.id, family.name, invitation.expires_at, invitation.created_at
    from public.family_invitations invitation
    join public.families family on family.id = invitation.family_id
    where invitation.status = 'pending' and invitation.expires_at > now()
      and (invitation.invited_user_id = actor_id or (invitation.invited_user_id is null and actor_email <> '' and lower(invitation.invited_email) = actor_email))
    order by invitation.created_at desc;
end;
$$;

create or replace function public.accept_family_invitation_by_id(p_invitation_id uuid)
returns uuid language plpgsql security definer set search_path = '' as $$
declare invitation public.family_invitations%rowtype; actor_id uuid := (select auth.uid()); actor_email text := lower(coalesce((select auth.jwt() ->> 'email'), ''));
begin
  if actor_id is null then raise exception 'Authentication is required'; end if;
  select * into invitation from public.family_invitations where id = p_invitation_id and status = 'pending' and expires_at > now() for update;
  if not found then raise exception 'This invitation is invalid, expired, or already used'; end if;
  if invitation.invited_user_id is not null and invitation.invited_user_id <> actor_id then
    raise exception 'This invitation belongs to another account';
  end if;
  if invitation.invited_user_id is null and (actor_email = '' or lower(invitation.invited_email) <> actor_email) then
    raise exception 'Sign in with the email address that received this invitation';
  end if;
  insert into public.family_memberships (family_id, user_id, role) values (invitation.family_id, actor_id, 'member') on conflict (family_id, user_id) do nothing;
  update public.family_invitations set status = 'accepted', accepted_by = actor_id, accepted_at = now() where id = invitation.id;
  insert into public.family_activity (family_id, actor_user_id, action, entity_type, entity_id) values (invitation.family_id, actor_id, 'accepted', 'invitation', invitation.id);
  return invitation.family_id;
end;
$$;

create function public.create_family_invitation_by_jibon_id(p_family_id uuid, p_jibon_id text)
returns uuid language plpgsql security definer set search_path = '' as $$
declare actor_id uuid := (select auth.uid()); target_user_id uuid; target_email text; invitation_id uuid; normalized_id text := upper(trim(coalesce(p_jibon_id, '')));
begin
  if actor_id is null then raise exception 'Authentication is required'; end if;
  if normalized_id !~ '^JBN-U-[A-F0-9]{10}$' then raise exception 'Enter a valid Jibon ID'; end if;
  if not app_private.has_family_role(p_family_id, array['owner', 'admin']::public.family_role[]) then raise exception 'Only a family owner or admin can invite members'; end if;
  select profile.id into target_user_id from public.profiles profile where profile.jibon_id = normalized_id;
  if target_user_id is null or target_user_id = actor_id then raise exception 'This account cannot receive this invitation'; end if;
  if exists (select 1 from public.family_memberships where family_id = p_family_id and user_id = target_user_id) then raise exception 'This person already belongs to the family'; end if;
  select email into target_email from auth.users where id = target_user_id;
  if target_email is null then raise exception 'This account cannot receive this invitation'; end if;
  insert into public.family_invitations (family_id, invited_email, invited_user_id, invited_by, token_hash)
    values (p_family_id, lower(target_email), target_user_id, actor_id, encode(extensions.digest(gen_random_uuid()::text, 'sha256'), 'hex'))
    returning id into invitation_id;
  return invitation_id;
exception when unique_violation then raise exception 'A pending invitation already exists for this person';
end;
$$;

create function public.get_jibon_identity(p_family_id uuid)
returns table (jibon_id text, family_code text, family_code_enabled boolean, can_manage_family_code boolean)
language plpgsql security definer set search_path = '' as $$
declare actor_id uuid := (select auth.uid()); can_manage boolean;
begin
  if actor_id is null then raise exception 'Authentication is required'; end if;
  select app_private.has_family_role(p_family_id, array['owner']::public.family_role[]) into can_manage;
  return query select profile.jibon_id, case when can_manage then family.invite_code else null end, case when can_manage then family.invite_code_enabled else false end, can_manage
    from public.profiles profile cross join public.families family
    where profile.id = actor_id and family.id = p_family_id and app_private.has_family_access(p_family_id);
end;
$$;

create function public.rotate_family_invite_code(p_family_id uuid)
returns text language plpgsql security definer set search_path = '' as $$
declare next_code text;
begin
  if auth.uid() is null or not app_private.has_family_role(p_family_id, array['owner']::public.family_role[]) then raise exception 'Only the family owner can rotate this code'; end if;
  next_code := app_private.new_family_invite_code();
  update public.families set invite_code = next_code, invite_code_enabled = true, invite_code_rotated_at = now() where id = p_family_id;
  insert into public.family_activity (family_id, actor_user_id, action, entity_type, entity_id) values (p_family_id, auth.uid(), 'rotated_invite_code', 'family', p_family_id);
  return next_code;
end;
$$;

create function public.request_join_family_by_code(p_family_code text)
returns uuid language plpgsql security definer set search_path = '' as $$
declare actor_id uuid := (select auth.uid()); target_family_id uuid; request_id uuid; normalized_code text := upper(trim(coalesce(p_family_code, '')));
begin
  if actor_id is null then raise exception 'Authentication is required'; end if;
  select id into target_family_id from public.families where invite_code = normalized_code and invite_code_enabled;
  if target_family_id is null or exists (select 1 from public.family_memberships where family_id = target_family_id and user_id = actor_id) then raise exception 'This family code cannot be used'; end if;
  insert into public.family_join_requests (family_id, requester_user_id) values (target_family_id, actor_id) returning id into request_id;
  insert into public.family_activity (family_id, actor_user_id, action, entity_type, entity_id) values (target_family_id, actor_id, 'requested_to_join', 'join_request', request_id);
  return request_id;
exception when unique_violation then raise exception 'A join request is already pending for this family';
end;
$$;

create function public.get_family_join_requests(p_family_id uuid)
returns table (request_id uuid, requester_jibon_id text, requester_name text, created_at timestamptz)
language plpgsql security definer set search_path = '' as $$
begin
  if auth.uid() is null or not app_private.has_family_role(p_family_id, array['owner', 'admin']::public.family_role[]) then raise exception 'Only a family owner or admin can view join requests'; end if;
  return query select request.id, profile.jibon_id, profile.display_name, request.created_at
    from public.family_join_requests request join public.profiles profile on profile.id = request.requester_user_id
    where request.family_id = p_family_id and request.status = 'pending' order by request.created_at desc;
end;
$$;

create function public.review_family_join_request(p_request_id uuid, p_approved boolean)
returns uuid language plpgsql security definer set search_path = '' as $$
declare request public.family_join_requests%rowtype; actor_id uuid := (select auth.uid());
begin
  if actor_id is null then raise exception 'Authentication is required'; end if;
  select * into request from public.family_join_requests where id = p_request_id and status = 'pending' for update;
  if not found then raise exception 'This join request is no longer pending'; end if;
  if not app_private.has_family_role(request.family_id, array['owner', 'admin']::public.family_role[]) then raise exception 'Only a family owner or admin can review this request'; end if;
  update public.family_join_requests set status = case when p_approved then 'approved' else 'declined' end, reviewed_by = actor_id, reviewed_at = now() where id = request.id;
  if p_approved then insert into public.family_memberships (family_id, user_id, role) values (request.family_id, request.requester_user_id, 'member') on conflict (family_id, user_id) do nothing; end if;
  insert into public.family_activity (family_id, actor_user_id, action, entity_type, entity_id) values (request.family_id, actor_id, case when p_approved then 'approved_join_request' else 'declined_join_request' end, 'join_request', request.id);
  return request.family_id;
end;
$$;

revoke all on function app_private.new_jibon_user_id() from public, anon, authenticated;
revoke all on function app_private.new_family_invite_code() from public, anon, authenticated;
revoke all on function public.create_family_invitation_by_jibon_id(uuid, text) from public, anon;
revoke all on function public.get_jibon_identity(uuid) from public, anon;
revoke all on function public.rotate_family_invite_code(uuid) from public, anon;
revoke all on function public.request_join_family_by_code(text) from public, anon;
revoke all on function public.get_family_join_requests(uuid) from public, anon;
revoke all on function public.review_family_join_request(uuid, boolean) from public, anon;
grant execute on function public.create_family_invitation_by_jibon_id(uuid, text) to authenticated;
grant execute on function public.get_jibon_identity(uuid) to authenticated;
grant execute on function public.rotate_family_invite_code(uuid) to authenticated;
grant execute on function public.request_join_family_by_code(text) to authenticated;
grant execute on function public.get_family_join_requests(uuid) to authenticated;
grant execute on function public.review_family_join_request(uuid, boolean) to authenticated;
